Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;

public class CF375B {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        sc.nextLine(); // skip first line
        String s = sc.next().toLowerCase();

        // Replace parentheses and underscores with spaces
        String cleaned = s.replaceAll("\\(.*?\\)", " ").replace('_', ' ');

        // Use streams to process tokens
        List<Integer> lengths = Arrays.stream(cleaned.split("\\s+"))
                .filter(t -> !t.isEmpty())
                .map(String::length)
                .collect(ArrayList::new, List::add, List::addAll);

        if (lengths.isEmpty()) {
            System.out.print("0 0");
        } else {
            int max = lengths.stream().mapToInt(Integer::intValue).max().getAsInt();
            System.out.print(max + " " + lengths.size());
        }
    }
}
